  static List<String> get categories =>
      devices.map((d) => d.category).toSet().toList()..sort();

  static List<DeviceLibraryEntry> byCategory(String category) =>
      devices.where((d) => d.category == category).toList();

  static List<DeviceLibraryEntry> search(String query) {
    final q = query.toLowerCase();
    return devices.where((d) =>
      d.typeDescription.toLowerCase().contains(q) ||
      d.articleCode.contains(q) ||
      d.category.toLowerCase().contains(q)
    ).toList();
  }
